import{_ as o,o as t,c as i,a6 as n}from"./chunks/framework.ZMCvXf1_.js";const p=JSON.parse('{"title":"noorm init","description":"","frontmatter":{},"headers":[],"relativePath":"cli/init.md","filePath":"cli/init.md"}'),a={name:"cli/init.md"};function r(d,e,c,s,l,h){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="noorm-init" tabindex="-1">noorm init <a class="header-anchor" href="#noorm-init" aria-label="Permalink to “noorm init”">​</a></h1><p>Bootstrap a new noorm project interactively. Creates identity (if not present), project structure (<code>sql/</code>, <code>changes/</code>, <code>.noorm/</code>), <code>settings.yml</code>, and <code>state.enc</code>.</p><h2 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to “Flags”">​</a></h2><ul><li><code>--force</code> / <code>-f</code> — overwrite an existing <code>.noorm/</code> directory</li><li><code>--here</code> — initialize in the original cwd, ignoring any parent <code>.noorm/</code> discovered while walking up</li><li><code>--yes</code> / <code>-y</code> — proceed non-interactively when a full identity already exists at <code>~/.noorm/identity.{key,pub,json}</code>. Equivalent to setting <code>NOORM_YES=1</code>. See <a href="./../guide/automation/non-interactive.html">Non-interactive operation</a> for details.</li></ul><h2 id="picking-the-project-root" tabindex="-1">Picking the project root <a class="header-anchor" href="#picking-the-project-root" aria-label="Permalink to “Picking the project root”">​</a></h2><p>Every <code>noorm</code> invocation walks up from the current directory looking for a <code>.noorm/</code> folder, then <code>chdir</code>s into it. That is what lets you run commands from deep inside a repo without thinking about paths. It also means <code>noorm init</code> from a subfolder of an already-initialized project tries to re-init the <em>parent</em>.</p><p>Two flags opt out of that behavior, depending on where you want to invoke from:</p><ul><li><code>noorm init --here</code> — stay in the cwd you launched from. Use this when you want to nest a fresh noorm project inside one that already exists (e.g. a <code>packages/db/</code> workspace under a repo that has its own <code>.noorm/</code>).</li><li><code>noorm -c &lt;path&gt; init</code> — global flag (must precede the subcommand, like <code>git -C</code>). Resolves <code>&lt;path&gt;</code> relative to the current shell, <code>chdir</code>s into it, and skips the walk-up entirely.</li></ul><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to “Environment”">​</a></h2><p>Interactive TTY required by default. Fails with exit code 2 (usage error) in CI or piped stdin unless <code>--yes</code> / <code>NOORM_YES=1</code> is set AND a full identity already exists.</p><h2 id="non-interactive-ci-flow" tabindex="-1">Non-interactive (CI) flow <a class="header-anchor" href="#non-interactive-ci-flow" aria-label="Permalink to “Non-interactive (CI) flow”">​</a></h2><p><code>noorm init --yes</code> (or <code>NOORM_YES=1 noorm init</code>) skips all prompts when a full crypto identity already lives at <code>~/.noorm/identity.{key,pub,json}</code>. The identity must be in place first — <code>--yes</code> does NOT bootstrap one. If any of the three files is missing, <code>noorm init --yes</code> exits 2 with:</p><pre><code>Error: noorm init --yes requires an existing identity at ~/.noorm/identity.{key,pub,json}.
Run: noorm identity init --name &quot;Your Name&quot; --email &quot;you@example.com&quot;
Then re-run: noorm init --yes
</code></pre><p>The end-to-end CI bootstrap is two commands:</p><pre><code># CI flow
noorm identity init --name &quot;$CI_USER&quot; --email &quot;$CI_EMAIL&quot;
noorm init --yes
</code></pre><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><pre><code>noorm init
noorm init --force
noorm init --here
noorm init --yes                 # non-interactive, requires existing identity

# From the repo root, init a sub-project at packages/db
noorm -c packages/db init
</code></pre><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><p>After <code>init</code> lays down <code>settings.yml</code> and <code>.noorm/</code>, the database itself still has to be provisioned. See <a href="./../guide/database/create.html">Creating a database</a> for the configs-first workflow (<code>config import</code> → <code>db create</code> → <code>config use</code>), and <a href="./flags.html">CLI flag conventions</a> for <code>--json</code> placement and the global-vs-per-subcommand rules.</p>`,19)])])}const f=o(a,[["render",r]]);export{p as __pageData,f as default};
